create table "sys_user" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "email" text not null,
  "pwd_hash" text not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  "organization_id" bigint not null,
  constraint "sys_user_pk" primary key ("id")
);

create table "sys_organization" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "code" text not null,
  "logo" text null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  constraint "sys_organization_pk" primary key ("id")
);

create table "sys_view" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "icon" text not null,
  "path" text not null,
  "component_path" text not null,
  "sort" integer not null,
  "active" boolean not null default true,
  "type" text not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  "parent_id" bigint null,
  constraint "sys_view_pk" primary key ("id")
);

create table "sys_role" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  constraint "sys_role_pk" primary key ("id")
);

create table "sys_role_user_mapping" (
  "role_id" bigint not null,
  "user_id" bigint not null,
  constraint "sys_role_user_mapping_pk" primary key ("role_id", "user_id")
);

create table "sys_role_view_mapping" (
  "role_id" bigint not null,
  "view_id" bigint not null,
  constraint "sys_role_view_mapping_pk" primary key ("role_id", "view_id")
);

create table "sys_permission" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  constraint "sys_permission_pk" primary key ("id")
);

create table "sys_role_permission_mapping" (
  "role_id" bigint not null,
  "permission_id" bigint not null,
  constraint "sys_role_permission_mapping_pk" primary key ("role_id", "permission_id")
);

alter table "sys_user" add constraint "sys_user_fk_organization_id" foreign key ("organization_id") references "sys_organization" ("id");

alter table "sys_view" add constraint "sys_view_fk_parent_id" foreign key ("parent_id") references "sys_view" ("id");

alter table "sys_role_user_mapping" add constraint "sys_role_user_mapping_fk_role_id" foreign key ("role_id") references "sys_role" ("id");

alter table "sys_role_user_mapping" add constraint "sys_role_user_mapping_fk_user_id" foreign key ("user_id") references "sys_user" ("id");

alter table "sys_role_view_mapping" add constraint "sys_role_view_mapping_fk_role_id" foreign key ("role_id") references "sys_role" ("id");

alter table "sys_role_view_mapping" add constraint "sys_role_view_mapping_fk_view_id" foreign key ("view_id") references "sys_view" ("id");

alter table "sys_role_permission_mapping" add constraint "sys_role_permission_mapping_fk_role_id" foreign key ("role_id") references "sys_role" ("id");

alter table "sys_role_permission_mapping" add constraint "sys_role_permission_mapping_fk_permission_id" foreign key ("permission_id") references "sys_permission" ("id");
